def msgfmt(po):
    """Minimal .po -> .mo compiler mirroring CPython's Tools/i18n/msgfmt.py."""
    messages = {}
    def add(ctxt, mid, mstr, fuzzy):
        if not fuzzy and mstr:
            messages[mid if ctxt is None else ctxt + b"\x04" + mid] = mstr
    ID, STR, CTXT = 1, 2, 3
    section = msgctxt = None
    fuzzy = False
    msgid = msgstr = b""
    for line in po.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") and section == STR:
            add(msgctxt, msgid, msgstr, fuzzy)
            section = msgctxt = None
            fuzzy = False
        if line.startswith("#,") and "fuzzy" in line:
            fuzzy = True
        if line.startswith("#"):
            continue
        if line.startswith("msgctxt"):
            if section == STR:
                add(msgctxt, msgid, msgstr, fuzzy)
                fuzzy = False
            section, line, msgctxt = CTXT, line[7:], b""
        elif line.startswith("msgid_plural"):
            line, msgid = line[12:], msgid + b"\0"
        elif line.startswith("msgid"):
            if section == STR:
                add(msgctxt, msgid, msgstr, fuzzy)
                msgctxt = None
                fuzzy = False
            section, line, msgid, msgstr = ID, line[5:], b"", b""
        elif line.startswith("msgstr"):
            section = STR
            if line.startswith("msgstr["):
                line = line.split("]", 1)[1]
                if msgstr:
